593→// createBranch creates a new local branch pointing at HEAD without checking it out.
594→func createBranch(repo *git.Repository, branchName string) error {
595→	head, err := repo.Head()
596→	if err != nil {
597→		return fmt.Errorf("failed to get HEAD: %w", err)
598→	}
599→	ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), head.Hash())
600→	if err := repo.Storer.SetReference(ref); err != nil {
601→		return fmt.Errorf("failed to create branch ref: %w", err)
602→	}
603→	return nil
