103→// buildTrailEntries creates blob objects for a trail's 3 files and returns them as tree entries.
104→func (s *Store) buildTrailEntries(metadata *Metadata, discussion *Discussion, checkpoints *Checkpoints) ([]object.TreeEntry, error) {
105→	if discussion == nil {
106→		discussion = &Discussion{Comments: []Comment{}}
107→	}
108→	if checkpoints == nil {
109→		checkpoints = &Checkpoints{Checkpoints: []CheckpointRef{}}
110→	}
111→
112→	type fileSpec struct {
113→		name string
114→		data any
115→	}
116→	files := []fileSpec{
117→		{metadataFile, metadata},
118→		{discussionFile, discussion},
119→		{checkpointsFile, checkpoints},
120→	}
121→
122→	entries := make([]object.TreeEntry, 0, len(files))
123→	for _, f := range files {
124→		jsonBytes, err := json.MarshalIndent(f.data, "", "  ")
125→		if err != nil {
126→			return nil, fmt.Errorf("failed to marshal %s: %w", f.name, err)
127→		}
128→		blobHash, err := checkpoint.CreateBlobFromContent(s.repo, jsonBytes)
129→		if err != nil {
130→			return nil, fmt.Errorf("failed to create %s blob: %w", f.name, err)
131→		}
132→		entries = append(entries, object.TreeEntry{
133→			Name: f.name,
134→			Mode: filemode.Regular,
135→			Hash: blobHash,
136→		})
137→	}
138→
139→	return entries, nil
140→}
